import{_ as r,o as d,c as e,ag as a}from"./chunks/framework.OsDJF_Ea.js";const g=JSON.parse('{"title":"CRM 모듈 (기관관리자)","description":"","frontmatter":{},"headers":[],"relativePath":"04-org-admin-guide/modules-crm.md","filePath":"04-org-admin-guide/modules-crm.md","lastUpdated":1780579853000}'),o={name:"04-org-admin-guide/modules-crm.md"};function i(l,t,n,h,s,c){return d(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="crm-모듈-기관관리자" tabindex="-1">CRM 모듈 (기관관리자) <a class="header-anchor" href="#crm-모듈-기관관리자" aria-label="Permalink to &quot;CRM 모듈 (기관관리자)&quot;">​</a></h1><p>기관 구성원이 고객사·담당자·명함·미팅·견적·내 핸드폰 연락처 동기화를 통합으로 다룰 수 있도록 CRM 모듈을 활성화합니다.</p><blockquote><p><strong>데이터 범위는 기관 공유</strong>: CRM 의 고객사 / 담당자 / 명함 / 미팅 데이터는 기관 단위로 <strong>모든 구성원이 공유</strong> 합니다. 핸드폰 연락처 동기화만 사용자 본인의 Google 계정에 따로 보관됩니다.</p></blockquote><hr><h2 id="_1-사전-조건" tabindex="-1">1. 사전 조건 <a class="header-anchor" href="#_1-사전-조건" aria-label="Permalink to &quot;1. 사전 조건&quot;">​</a></h2><table tabindex="0"><thead><tr><th>항목</th><th>필수 / 권장</th><th>비고</th></tr></thead><tbody><tr><td>(없음 — 단독 활성 가능)</td><td>—</td><td>CRM 단독으로도 동작</td></tr><tr><td><strong>Drive 모듈</strong> 활성</td><td>권장</td><td>명함 Drive 인박스 / 미팅 트랜스크립트 Drive 가져오기 사용 시 필요</td></tr><tr><td><strong>AI API 키</strong> (Gemini) 등록</td><td>권장</td><td>명함 OCR · 미팅 요약 · 고객사 매칭 제안 사용 시 필요</td></tr><tr><td><strong>Google 모듈</strong></td><td>선택</td><td>&quot;내 핸드폰 연락처 동기화&quot; 기능 (People API) 사용 시</td></tr></tbody></table><p>→ Drive / AI 키 미설정 시 해당 기능만 비활성. CRM 핵심 (고객사 / 담당자 / 견적) 은 동작.</p><hr><h2 id="_2-모듈-활성화" tabindex="-1">2. 모듈 활성화 <a class="header-anchor" href="#_2-모듈-활성화" aria-label="Permalink to &quot;2. 모듈 활성화&quot;">​</a></h2><p>좌측 사이드바 → <strong>관리자 → 모듈 관리</strong> (<code>/app/admin/modules</code>) → <strong>&quot;CRM&quot;</strong> 카드 토글 ON.</p><p>활성화 직후 좌측 사이드바에 <strong>고객관리</strong> 메뉴가 추가됩니다.</p><hr><h2 id="_3-설정-—-명함-drive-인박스-폴더" tabindex="-1">3. 설정 — 명함 Drive 인박스 폴더 <a class="header-anchor" href="#_3-설정-—-명함-drive-인박스-폴더" aria-label="Permalink to &quot;3. 설정 — 명함 Drive 인박스 폴더&quot;">​</a></h2><p>CRM 모듈 카드의 <strong>[설정]</strong> 패널 (Drive 모듈이 활성화돼 있을 때만 표시):</p><table tabindex="0"><thead><tr><th>항목</th><th>설명</th></tr></thead><tbody><tr><td><strong>명함 Drive 폴더</strong></td><td>사용자가 폰으로 찍은 명함 사진을 업로드할 Drive 폴더. 비워두면 자동 생성 (<code>/Workhub/CRM/명함-인박스/</code>)</td></tr><tr><td><strong>트랜스크립트 폴더</strong> (자동)</td><td>미팅 트랜스크립트 원본을 보관할 폴더 — 자동 lazy create</td></tr></tbody></table><p><strong>lazy create</strong>: 폴더 설정을 비워두거나 존재하지 않는 ID 를 입력하면, 첫 사용 시 워크허브가 자동으로 폴더를 생성합니다. 기존 폴더를 쓰려면 Drive 의 폴더 URL <code>/drive/folders/XXX</code> 의 XXX 를 복사해 입력.</p><hr><h2 id="_4-ai-api-키-gemini-—-의존성" tabindex="-1">4. AI API 키 (Gemini) — 의존성 <a class="header-anchor" href="#_4-ai-api-키-gemini-—-의존성" aria-label="Permalink to &quot;4. AI API 키 (Gemini) — 의존성&quot;">​</a></h2><p>다음 기능은 Gemini API 키가 등록돼 있어야 동작합니다:</p><table tabindex="0"><thead><tr><th>기능</th><th>위치</th></tr></thead><tbody><tr><td>명함 이미지 OCR (Vision)</td><td>고객관리 → 명함 → Drive 인박스 → [OCR 처리]</td></tr><tr><td>명함 텍스트 붙여넣기 파싱</td><td>고객관리 → 명함 → [텍스트 붙여넣기]</td></tr><tr><td>미팅 트랜스크립트 요약</td><td>고객관리 → 미팅 → 트랜스크립트 ingest</td></tr><tr><td>고객사 매칭 제안</td><td>명함 확정 시 자동</td></tr></tbody></table><p>키 등록 방법: <a href="./ai-api-keys.html">AI API 키 설정</a></p><p>키 미등록 시 해당 기능은 화면에 &quot;AI 설정에서 Gemini API 키를 등록해주세요&quot; 안내로 자동 fallback.</p><hr><h2 id="_5-데이터-범위-기관-공유-vs-개인" tabindex="-1">5. 데이터 범위 (기관 공유 vs 개인) <a class="header-anchor" href="#_5-데이터-범위-기관-공유-vs-개인" aria-label="Permalink to &quot;5. 데이터 범위 (기관 공유 vs 개인)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>데이터</th><th>범위</th><th>비고</th></tr></thead><tbody><tr><td>고객사 (<code>customers</code>)</td><td><strong>기관 공유</strong></td><td>모든 사용자가 조회/편집</td></tr><tr><td>담당자 (<code>crm_contacts</code>)</td><td><strong>기관 공유</strong></td><td>모든 사용자가 조회/편집</td></tr><tr><td>명함 (<code>crm_business_cards</code>)</td><td><strong>기관 공유</strong></td><td>인박스 단계에서는 업로더 표시, 확정 후 공유</td></tr><tr><td>미팅 (<code>crm_meetings</code>)</td><td><strong>기관 공유</strong></td><td>모든 사용자 조회</td></tr><tr><td>견적 (<code>crm_quotes</code>)</td><td><strong>기관 공유</strong></td><td>모든 사용자 조회 (재무 모듈과 연동)</td></tr><tr><td><strong>핸드폰 연락처 매핑</strong></td><td><strong>개인</strong></td><td>사용자 본인 Google People API 계정에만 저장</td></tr></tbody></table><p>→ 핸드폰 sync 만 사용자 단위로 분리됩니다. 자세히는 <a href="./../02-user-guide/crm-phone-sync.html">명함 → 내 핸드폰 연락처 동기화 (사용자 가이드)</a>.</p><hr><h2 id="_6-다른-모듈과의-연동" tabindex="-1">6. 다른 모듈과의 연동 <a class="header-anchor" href="#_6-다른-모듈과의-연동" aria-label="Permalink to &quot;6. 다른 모듈과의 연동&quot;">​</a></h2><table tabindex="0"><thead><tr><th>연동</th><th>흐름</th></tr></thead><tbody><tr><td><strong>재무 모듈</strong></td><td>견적 → 계약 승격, 명함 → finance_clients 자동 매칭</td></tr><tr><td><strong>태스크</strong></td><td>미팅 → 태스크 자동 생성 (<code>source_meeting_id</code> 기록)</td></tr><tr><td><strong>Drive 모듈</strong></td><td>명함 사진 / 미팅 첨부 / 트랜스크립트 원본을 Drive 에 보관</td></tr><tr><td><strong>Gmail 모듈</strong></td><td>메일 → 태스크 → 미팅 / 견적 흐름 (역참조)</td></tr></tbody></table><hr><h2 id="_7-모듈-비활성화-시-영향" tabindex="-1">7. 모듈 비활성화 시 영향 <a class="header-anchor" href="#_7-모듈-비활성화-시-영향" aria-label="Permalink to &quot;7. 모듈 비활성화 시 영향&quot;">​</a></h2><table tabindex="0"><thead><tr><th>항목</th><th>영향</th></tr></thead><tbody><tr><td>좌측 사이드바 <strong>고객관리</strong> 메뉴</td><td>즉시 사라짐</td></tr><tr><td>고객사 / 담당자 / 명함 / 미팅 데이터</td><td>DB 에 보관 (재활성 시 복구)</td></tr><tr><td>사용자의 핸드폰 sync OAuth 토큰</td><td>보관됨 (재활성 시 복구)</td></tr><tr><td>견적 → 재무 계약 승격 연결</td><td>기존 데이터 그대로, 새 승격은 비활성</td></tr><tr><td>Drive 명함 인박스</td><td>Drive 폴더는 그대로 남음 — 워크허브에서만 인식 중단</td></tr></tbody></table><hr><h2 id="_8-트러블슈팅" tabindex="-1">8. 트러블슈팅 <a class="header-anchor" href="#_8-트러블슈팅" aria-label="Permalink to &quot;8. 트러블슈팅&quot;">​</a></h2><h3 id="명함-drive-인박스가-안-보임" tabindex="-1">명함 Drive 인박스가 안 보임 <a class="header-anchor" href="#명함-drive-인박스가-안-보임" aria-label="Permalink to &quot;명함 Drive 인박스가 안 보임&quot;">​</a></h3><p>체크:</p><ol><li>CRM 모듈 ON</li><li>Drive 모듈 ON</li><li>명함 Drive 폴더 설정값 정상 (또는 lazy create 가 동작했는지)</li><li>사용자가 본인 Drive OAuth 동의 완료</li></ol><h3 id="명함-ocr-클릭-시-ai-키를-등록해주세요" tabindex="-1">명함 OCR 클릭 시 &quot;AI 키를 등록해주세요&quot; <a class="header-anchor" href="#명함-ocr-클릭-시-ai-키를-등록해주세요" aria-label="Permalink to &quot;명함 OCR 클릭 시 &quot;AI 키를 등록해주세요&quot;&quot;">​</a></h3><ul><li>AI API 키 미등록 — <a href="./ai-api-keys.html">AI API 키 설정</a> 으로 등록</li></ul><h3 id="견적이-재무-모듈로-안-올라옴" tabindex="-1">견적이 재무 모듈로 안 올라옴 <a class="header-anchor" href="#견적이-재무-모듈로-안-올라옴" aria-label="Permalink to &quot;견적이 재무 모듈로 안 올라옴&quot;">​</a></h3><ul><li>재무 모듈이 비활성인 경우 견적은 CRM 안에만 존재</li><li>재무 모듈 활성 후 견적 → 계약 승격 메뉴가 노출</li></ul><hr><h2 id="관련-가이드" tabindex="-1">관련 가이드 <a class="header-anchor" href="#관련-가이드" aria-label="Permalink to &quot;관련 가이드&quot;">​</a></h2><ul><li><a href="./ai-api-keys.html">AI API 키 설정</a> — OCR / 요약 / 매칭 제안에 필요</li><li><a href="./modules-gdrive.html">Drive 모듈 (관리자)</a> — 명함 Drive 인박스 / 미팅 트랜스크립트</li><li><a href="./modules-finance.html">재무 모듈 (관리자)</a> — 견적 → 계약 승격</li><li><a href="./modules-gmail.html">Gmail 모듈 (관리자)</a> — 메일 → 태스크 → CRM 흐름</li><li><a href="./../02-user-guide/crm-phone-sync.html">명함 → 내 핸드폰 연락처 동기화 (사용자 가이드)</a> — 사용자 핸드폰 sync</li></ul>',44)])])}const m=r(o,[["render",i]]);export{g as __pageData,m as default};
